/**
 * Print every English documentation URL, in the order the sidebar shows them.
 *
 * Written for feeding the docs to an outside reader — a third opinion on whether
 * the documentation contradicts itself. Menu order matters for that: a reader
 * going Introduction → Getting started → Core concepts sees the argument being
 * built, where an alphabetical list opens on `bindings/csharp` and never
 * establishes what a sequence is.
 *
 * The order is not written down anywhere to be read: `sidebars.js` says
 * `autogenerated`, so Docusaurus builds the menu from the folder tree, each
 * folder's `_category_.json` position, and each page's `sidebar_position`. This
 * reproduces that, which is the only way to get menu order without running a
 * build.
 *
 * `--check` compares the result against the published sitemap.xml and refuses if
 * they disagree — a page reachable on the site but missing here would be a hole
 * in exactly the kind of review this list exists to enable. That needs network;
 * without the flag the script is offline and instant.
 *
 *   node webdoc/scripts/list-doc-urls.mjs           # the list
 *   node webdoc/scripts/list-doc-urls.mjs --check   # + verify against the site
 */

import { readFileSync, readdirSync, statSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const DOCS = join(HERE, '..', 'docs');
const SITE = 'https://nickliapin.github.io/tdcv2';

/** Front matter is the first `---` fenced block; only two keys matter here. */
function frontMatter(file) {
  const text = readFileSync(file, 'utf8');
  const m = /^---\n([\s\S]*?)\n---/.exec(text);
  if (!m) return {};
  const out = {};
  for (const line of m[1].split('\n')) {
    const kv = /^(sidebar_position|slug|title):\s*(.+)$/.exec(line.trim());
    if (kv) out[kv[1]] = kv[2].replace(/^["']|["']$/g, '');
  }
  return out;
}

/**
 * One folder, sorted the way Docusaurus sorts it.
 *
 * Pages and sub-folders are interleaved by position — a category with
 * `"position": 4` sits between the pages numbered 3 and 5, it does not go after
 * all of them. Anything without a position sorts last, alphabetically, which is
 * also what Docusaurus does.
 */
function collect(dir, urlPrefix) {
  const entries = [];
  for (const name of readdirSync(dir)) {
    const path = join(dir, name);
    if (statSync(path).isDirectory()) {
      let position = Number.POSITIVE_INFINITY;
      let label = name;
      try {
        const category = JSON.parse(readFileSync(join(path, '_category_.json'), 'utf8'));
        if (typeof category.position === 'number') position = category.position;
        if (category.label) label = category.label;
      } catch {
        /* a folder without _category_.json still appears, just unpositioned */
      }
      entries.push({ kind: 'dir', path, name, position, label });
    } else if (name.endsWith('.mdx') || name.endsWith('.md')) {
      const fm = frontMatter(path);
      entries.push({
        kind: 'page',
        name,
        position: fm.sidebar_position === undefined ? Number.POSITIVE_INFINITY : Number(fm.sidebar_position),
        title: fm.title ?? name.replace(/\.mdx?$/, ''),
        // `slug: /intro` is absolute and replaces the path-derived URL.
        url: fm.slug?.startsWith('/')
          ? `${SITE}/docs${fm.slug}`
          : `${urlPrefix}/${name.replace(/\.mdx?$/, '')}`,
      });
    }
  }
  entries.sort((a, b) => a.position - b.position || a.name.localeCompare(b.name));

  const out = [];
  for (const e of entries) {
    if (e.kind === 'page') out.push({ url: e.url, title: e.title });
    else out.push(...collect(e.path, `${urlPrefix}/${e.name}`));
  }
  return out;
}

const pages = collect(DOCS, `${SITE}/docs`);

if (process.argv.includes('--bundle')) {
  /*
   * One markdown file instead of 67 links.
   *
   * A reader fetching the site gets the rendered page, and every page carries the
   * same sidebar, navbar and footer. Across 67 pages that is 67 copies of the menu
   * competing with the text — bad input for a reader asked whether the docs
   * contradict themselves, and most tools cap the number of sources anyway.
   *
   * `docs/` already holds the same pages as plain markdown, generated from these
   * sources and checked against them on every build, so it cannot say something
   * the site does not. Concatenated in menu order it reads as one document, with
   * each page's URL above it so any finding can be pointed back at a real page.
   */
  const EXPORT = join(HERE, '..', '..', 'docs');
  const parts = [
    '# TDC — the complete English documentation',
    '',
    `${String(pages.length)} pages, in the order the site's menu presents them. Each section below opens`,
    'with the URL of the page it came from.',
    '',
  ];
  for (const p of pages) {
    const slug = p.url.replace(`${SITE}/docs/`, '');
    const file = join(EXPORT, `${slug}.md`);
    let body;
    try {
      body = readFileSync(file, 'utf8');
    } catch {
      console.error(`missing export for ${slug} — run \`npm run docs:export\` first`);
      process.exit(1);
    }
    parts.push('\n\n---\n', `<!-- source: ${p.url} -->`, '', body.trim(), '');
  }
  process.stdout.write(`${parts.join('\n')}\n`);
} else if (process.argv.includes('--check')) {
  const xml = await (await fetch(`${SITE}/sitemap.xml`)).text();
  const live = new Set(
    [...xml.matchAll(/<loc>([^<]*)<\/loc>/g)]
      .map((m) => m[1].replace(/\/$/, ''))
      .filter((u) => u.includes('/docs/') || u.endsWith('/docs')),
  );
  const mine = new Set(pages.map((p) => p.url.replace(/\/$/, '')));
  const missing = [...live].filter((u) => !mine.has(u));
  const extra = [...mine].filter((u) => !live.has(u));
  if (missing.length > 0 || extra.length > 0) {
    for (const u of missing) console.error(`  on the site but not in this list: ${u}`);
    for (const u of extra) console.error(`  in this list but not on the site:  ${u}`);
    console.error('\nThe list is meant to be every English page. Fix it before handing it to a reviewer.');
    process.exit(1);
  }
  console.log(`${String(pages.length)} pages, and the published sitemap lists exactly the same set.`);
} else {
  for (const p of pages) console.log(p.url);
}
